{
  "name": "game-room",
  "private": true,
  "type": "module",
  "engines": {
    "node": ">=22.13.0"
  },
  "scripts": {
    "start": "node server/index.js"
  },
  "dependencies": {
    "@colyseus/core": "0.18.14",
    "@colyseus/schema": "5.0.33",
    "@colyseus/ws-transport": "0.18.2",
    "@colyseus/redis-driver": "0.18.2",
    "@colyseus/redis-presence": "0.18.4",
    "express": "4.21.2",
    "zod": "4.6.5",
    "@cloudbase/js-sdk": "3.10.4"
  }
}

import { hostname } from "node:os";
import { createServer } from "node:http";
import express from "express";
import { defineRoom, defineServer, matchMaker } from "@colyseus/core";
import { WebSocketTransport } from "@colyseus/ws-transport";
import { AFFINITY_HEADER, AFFINITY_QUERY } from "./runtime/protocol.js";
import { admitClient } from "./runtime/admission.js";
import { createClusterServerOptions } from "./runtime/cluster.js";
import { verifyTokenOrThrow } from "./runtime/auth.js";
import { CountRoom } from "./rooms/CountRoom.js";

const ROOM_TYPE = "count";
// 可观测版本号：改这一行并重新源码部署，即可通过 /health 验证更新是否生效。
const DEPLOY_VERSION = "v1";
const GAME_BUILD = `${DEPLOY_VERSION}-${ROOM_TYPE}`;


if (!process.env.GAME_APP_ID || !process.env.GAME_TOKEN_PUBLIC_KEY_B64) throw new Error("GAME_APP_ID and GAME_TOKEN_PUBLIC_KEY_B64 are required");
if (process.env.NODE_ENV === "production" && !process.env.REDIS_URL) throw new Error("REDIS_URL is required in production");
// The platform uses CLIENT_ORIGIN=* for both HTTP and WebSocket origins.
// Preserve the wildcard; an empty setting also defaults to *.
const allowedOrigins = (process.env.CLIENT_ORIGIN?.trim() || '*').split(',').map(value => value.trim()).filter(Boolean);
const originAllowed = origin => !origin || allowedOrigins.includes('*') || allowedOrigins.includes(origin);
const httpServer = createServer();

const clusterOptions = process.env.REDIS_URL
  ? createClusterServerOptions({
      publicAddress: process.env.SHAPER_PUBLIC_ADDRESS,
      selectProcessIdToCreateRoom: () => matchMaker.processId,
      gracefullyShutdown: true,
    })
  : {};

export const server = defineServer({
  ...clusterOptions,
  transport: new WebSocketTransport({ server: httpServer, maxPayload: 65_536, verifyClient: info => originAllowed(info.origin) }),
  greet: false,
  rooms: { [ROOM_TYPE]: defineRoom(CountRoom) },
  express: (app) => {
    app.use(express.json({ limit: "16kb" }));
    app.use((req, res, next) => {
      if (!originAllowed(req.headers.origin)) return res.status(403).json({ error: "ORIGIN_NOT_ALLOWED" });
      res.setHeader("Access-Control-Allow-Origin", allowedOrigins.includes('*') ? '*' : (req.headers.origin || allowedOrigins[0]));
      res.setHeader("Vary", "Origin");
      res.setHeader("Access-Control-Allow-Methods", "GET,POST,OPTIONS");
      res.setHeader("Access-Control-Allow-Headers", "Origin, X-Requested-With, Content-Type, Accept, Authorization, X-Hupu-Token");
      res.setHeader("Access-Control-Expose-Headers", AFFINITY_HEADER);
      if (req.method === "OPTIONS") {
        res.sendStatus(204);
        return;
      }
      next();
    });

    app.get("/health", async (_req, res) => {
      let redis = clusterOptions.presence ? 'unavailable' : 'disabled';
      let timer;
      try {
        if (clusterOptions.presence) {
          await Promise.race([
            clusterOptions.presence.exists('health-probe'),
            new Promise((_, reject) => { timer = setTimeout(() => reject(new Error('Redis timeout')), 2000); }),
          ]);
          redis = 'connected';
        }
        res.json({ ok: true, instanceId: hostname(), version: GAME_BUILD, redis,
          appId: process.env.GAME_APP_ID, publicAddress: process.env.SHAPER_PUBLIC_ADDRESS || '' });
      } catch {
        res.status(503).json({ ok: false, redis: 'unavailable' });
      } finally { clearTimeout(timer); }
    });

    app.get("/rooms", async (_req, res) => {
      const rooms = await matchMaker.query({ name: ROOM_TYPE });
      res.json({
        rooms: rooms.map((room) => ({ roomId: room.roomId, clients: room.clients, maxClients: room.maxClients })),
      });
    });

    // 服务端准入：先验签 Game Token，再交给 matchmaker；Room 的 onAuth 会再验一次。
    app.post("/admit", async (req, res) => {
      const gameToken = typeof req.body?.gameToken === "string" ? req.body.gameToken : undefined;
      try {
        verifyTokenOrThrow(gameToken);
      } catch {
        res.status(401).json({ error: "INVALID_GAME_TOKEN", message: "游戏身份令牌无效或已过期" });
        return;
      }
      const affinity = typeof req.query[AFFINITY_QUERY] === "string" ? req.query[AFFINITY_QUERY] : undefined;
      const result = await admitClient({ roomType: ROOM_TYPE, affinity, token: gameToken, options: {} });
      if (result.ok) res.json({ reservation: result.reservation, affinity: result.affinity });
      else res.status(result.status).json({ error: result.code, message: result.message });
    });
  },
});

const port = Number(process.env.PORT ?? 3000);
await server.listen(port, "0.0.0.0");
console.log(`[mp-count-room] listening on ${port} version=${GAME_BUILD} instance=${hostname()}`);

import { Room, ServerError } from "@colyseus/core";
import { schema, t } from "@colyseus/schema";
import { AFFINITY_METADATA_KEY, affinityFromOptions } from "../runtime/admission.js";
import { verifyTokenOrThrow } from "../runtime/auth.js";

const PlayerState = schema({ name: t.string() }, "CountPlayer");
const CountState = schema(
  { count: t.number().default(0), version: t.string(), players: t.map(PlayerState) },
  "CountState",
);

export class CountRoom extends Room {
  maxClients = 8;
  state = new CountState();

  /** 平台在部署时注入 GAME_APP_ID 与公钥；客户端传来的任何身份字段一律不信任。 */
  static async onAuth(token) {
    try {
      return verifyTokenOrThrow(typeof token === "string" ? token : undefined);
    } catch {
      throw new ServerError(401, "Invalid game token");
    }
  }

  async onCreate(options = {}) {
    const affinity = affinityFromOptions(options);
    if (affinity) await this.setMetadata({ ...this.metadata, [AFFINITY_METADATA_KEY]: affinity });
    this.state.version = "v1-count";
    this.state.count = 0;
    this.onMessage("increment", (client) => {
      const sub = client.auth?.sub;
      if (typeof sub !== "string" || sub.length === 0) return;
      this.state.count += 1;
    });
  }

  onJoin(client) {
    const player = new PlayerState();
    player.name = String(client.auth?.sub ?? client.sessionId);
    this.state.players.set(client.sessionId, player);
  }

  async onDrop(client) {
    try { await this.allowReconnection(client, 20); } catch { /* onLeave cleans up */ }
  }

  onLeave(client) {
    this.state.players.delete(client.sessionId);
  }
}

import { matchMaker } from "@colyseus/core";
import { AffinitySchema, MultiplayerError, SeatReservationSchema, } from "./protocol.js";
/**
 * `onCreate` option key carrying the CloudBase affinity token. The admission
 * helper writes it and the room reads it, so both sides share this constant
 * instead of repeating the string.
 */
export const AFFINITY_OPTION_KEY = "cloudbaseSessionId";
/** Room metadata key the affinity token is stored under. */
export const AFFINITY_METADATA_KEY = "cloudbaseSessionId";
/**
 * Extract the affinity token a room was created with.
 *
 * `Room.onCreate` / `onJoin` receive the merged join options, so a room only
 * needs to call this and spread the result into `setMetadata` (0.18 replaces
 * metadata wholesale, it does not merge).
 */
export function affinityFromOptions(options) {
    if (!options || typeof options !== "object")
        return undefined;
    const value = options[AFFINITY_OPTION_KEY];
    if (typeof value !== "string")
        return undefined;
    return AffinitySchema.safeParse(value).success ? value : undefined;
}
/**
 * Server-side admission: pick or create a room with the native matchmaker,
 * reserve a seat, then read back the room's affinity token.
 *
 * The affinity token is returned to the client so it can pin its WebSocket
 * upgrade to the instance that actually holds the room. Two outcomes are both
 * correct: joining a room on another instance yields that room's token, while a
 * locally created room yields the requester's own token (creation is forced
 * local by `selectProcessIdToCreateRoom`).
 */
export async function admitClient(request) {
    const roomType = request.roomType?.trim();
    if (!roomType) {
        return { ok: false, status: 400, code: "AFFINITY_REQUIRED", message: "缺少房间类型" };
    }
    if (typeof request.affinity !== "string" || request.affinity === "") {
        return {
            ok: false,
            status: 400,
            code: "AFFINITY_REQUIRED",
            message: "准入请求必须携带 cloudbase_session_id",
        };
    }
    if (!AffinitySchema.safeParse(request.affinity).success) {
        return { ok: false, status: 400, code: "AFFINITY_REQUIRED", message: "cloudbase_session_id 不合法" };
    }
    let reservation;
    try {
        const authContext = request.token === undefined ? undefined : {
            token: request.token,
            ip: undefined,
            headers: new Headers(),
        };
        const result = await matchMaker.joinOrCreate(roomType, {
            ...(request.options ?? {}),
            [AFFINITY_OPTION_KEY]: request.affinity,
        }, authContext);
        const parsed = SeatReservationSchema.safeParse(result);
        if (!parsed.success) {
            return { ok: false, status: 500, code: "ADMISSION_FAILED", message: "座位预约形状不合法" };
        }
        reservation = parsed.data;
    }
    catch (error) {
        return {
            ok: false,
            status: 503,
            code: "ADMISSION_FAILED",
            message: error instanceof MultiplayerError ? error.message : "匹配失败，请重试",
        };
    }
    let room;
    try {
        room = await matchMaker.getRoomById(reservation.roomId);
    }
    catch {
        return { ok: false, status: 503, code: "ADMISSION_FAILED", message: "读取房间信息失败，请重试" };
    }
    const affinity = room?.metadata?.[AFFINITY_METADATA_KEY];
    if (typeof affinity !== "string" || !AffinitySchema.safeParse(affinity).success) {
        return {
            ok: false,
            status: 409,
            code: "ROOM_AFFINITY_MISSING",
            message: "房间未记录亲和标识，拒绝准入",
        };
    }
    return { ok: true, reservation, affinity };
}

