# SDK 持久化适配器骨架

新项目从 [完整游戏模板](../game/README.md) 起步，复用 [getRdb](../game/server/runtime/cloudbase-pg.js)。平台注入 CloudBase 环境 ID、地域和 API Key；标准与旧 TCP 迁移要求见 [持久化](../../references/persistence.md)。

下面示范一次 RPC 原子记录奖励；它不是包含余额变更的完整结算。需要余额、库存联动时将所有操作放进同一个函数，并补充并发与回滚验收。玩家身份、奖励金额必须由可信服务端决定。

## 版本化迁移

通过项目迁移入口执行一次，不在 Room 启动或请求路径建表。示例按 CloudBase 的 service_role 设计，部署前确认实际运行身份与该角色的映射并验证授权。

```sql
CREATE TABLE public.reward_ledger (
  game_id text NOT NULL,
  actor_id text NOT NULL,
  command_id text NOT NULL,
  amount integer NOT NULL CHECK (amount > 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (game_id, actor_id, command_id)
);
ALTER TABLE public.reward_ledger ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.reward_ledger FROM PUBLIC;
GRANT SELECT, INSERT ON public.reward_ledger TO service_role;
CREATE POLICY reward_ledger_service ON public.reward_ledger
  FOR ALL TO service_role USING (true) WITH CHECK (true);

CREATE FUNCTION public.record_reward(
  p_game_id text, p_actor_id text, p_command_id text, p_amount integer
) RETURNS boolean
LANGUAGE plpgsql SECURITY INVOKER SET search_path = ''
AS $$
DECLARE inserted_count integer;
BEGIN
  INSERT INTO public.reward_ledger (game_id, actor_id, command_id, amount)
  VALUES (p_game_id, p_actor_id, p_command_id, p_amount)
  ON CONFLICT (game_id, actor_id, command_id) DO NOTHING;
  GET DIAGNOSTICS inserted_count = ROW_COUNT;
  RETURN inserted_count = 1;
END;
$$;
REVOKE ALL ON FUNCTION public.record_reward(text, text, text, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.record_reward(text, text, text, integer) TO service_role;
```

## 服务端适配器

```js
import { getRdb } from '../runtime/cloudbase-pg.js';

export async function writeReward({ gameId, actorId, commandId, amount }) {
  const { data, error } = await getRdb().rpc('record_reward', {
    p_game_id: gameId,
    p_actor_id: actorId,
    p_command_id: commandId,
    p_amount: amount,
  });
  if (error) throw new Error('PERSISTENCE_WRITE_FAILED');
  if (typeof data !== 'boolean') throw new Error('PERSISTENCE_RESPONSE_INVALID');
  return data; // true=本次写入；false=已记录相同命令
}
```

从异步权威命令调用并等待结果，成功后确认奖励。超时使用同一个 commandId 重试，不生成新幂等键。真实验收包括首次写入、相同命令重试不重复写入、非法金额回滚以及未授权玩家被 Room 拒绝；读库成功不能代替这些检查。

// Boundary sketch. Verify exact Room, client, Schema, and handler APIs against
// the upstream Colyseus v0.18.0 skill before compiling. `this.allowReconnection`
// below is inherited from the upstream `Room` base class; this file is an
// adapter sketch, not compilable on its own.

import { verifyGameToken } from "@shaper/multiplayer-server";

/**
 * Grace period for a dropped player. Pick the number from the decision table in
 * `references/reconnection.md` §3.3 (turn-based/co-op can afford a whole turn,
 * arena wants 5-15s, disposable party rooms want 0-5s). Keep it in one place so
 * it never leaks out as an inline magic number.
 */
const RECONNECT_GRACE_SECONDS = 10;

type RoomContext = {
  clock: { now(): number };
  domain: {
    accept(command: unknown, playerId: string): { ok: true; state: unknown } | { ok: false; code: string };
    /** Projection only: the seat stays, but the player is flagged as absent. */
    markDisconnected(playerId: string): void;
    markReconnected(playerId: string): void;
    /** Grace period expired: settle by the chosen policy (forfeit, spectate, ...). */
    forfeit(playerId: string): void;
    /** Idempotent seat release. Called for consented leave and after a drop. */
    release(playerId: string, code: number): void;
  };
};

export class ExampleRoom {
  private context!: RoomContext;

  static onAuth(token: string | undefined) {
    return verifyGameToken(token, {
      appId: process.env.GAME_APP_ID ?? "",
      publicKey: Buffer.from(process.env.GAME_TOKEN_PUBLIC_KEY_B64 ?? "", "base64").toString("utf8"),
    });
  }

  onCreate(options: unknown) {
    this.context = createContext(options);
    // Register the room state and inbound game-specific protocol handlers here.
    // Keep handlers thin: decode, validate transport metadata, call domain.
  }

  onJoin(client: { sessionId: string; auth: { sub: string } }, options: unknown) {
    // Admission is based on the verified principal returned by onAuth.
    void client;
    void options;
  }

  onMessage(client: { auth: { sub: string } }, message: unknown) {
    const result = this.context.domain.accept(message, client.auth.sub);
    if (!result.ok) {
      // Send a stable error code through the upstream-supported response path.
      return { error: result.code };
    }
    return result.state;
  }

  /**
   * Non-voluntary close. Do not delete the seat here: within the grace period
   * the player can still come back, and Colyseus calls `onLeave` again once the
   * grace period expires without a reconnect (see `references/reconnection.md` §3.1).
   */
  onDrop(client: { sessionId: string }, code: number) {
    this.context.domain.markDisconnected(client.sessionId);
    void code;
    void this.allowReconnection(client, RECONNECT_GRACE_SECONDS).then(
      () => {}, // recovery is handled in onReconnect
      () => this.context.domain.forfeit(client.sessionId), // grace expired -> settle by policy
    );
  }

  /** The seat survived; restore the player and let the projection flip back. */
  onReconnect(client: { sessionId: string }) {
    this.context.domain.markReconnected(client.sessionId);
  }

  /**
   * Reached for a consented leave (4000), a second time after every drop, and
   * when a reconnect handshake fails (4003). Must be idempotent: release the
   * seat, drop buffered input, and stop only this player's timers.
   */
  onLeave(client: { sessionId: string }, code: number) {
    this.context.domain.release(client.sessionId, code);
  }

  onDispose() {
    // Stop timers, detach listeners, and flush only bounded explicit effects.
  }
}

function createContext(options: unknown): RoomContext {
  void options;
  throw new Error("Wire the domain service and clock here");
}

// State projection sketch. Keep only fields clients need to render or decide.

export type ExampleState = {
  phase: "lobby" | "active" | "finished";
  serverTick: number;
  players: Array<{
    id: string;
    displayName: string;
    ready: boolean;
    score: number;
  }>;
};

export function projectState(domainState: {
  phase: ExampleState["phase"];
  serverTick: number;
  players: Array<{ id: string; displayName: string; ready: boolean; score: number }>;
}): ExampleState {
  return {
    phase: domainState.phase,
    serverTick: domainState.serverTick,
    players: domainState.players.map((player) => ({ ...player })),
  };
}

// Integration-test outline. Use the test client and exact lifecycle helpers
// from the upstream Colyseus v0.18.0 skill. The reconnect cases encode the
// contract fixed by `references/reconnection.md` §8.

describe("example room contract", () => {
  it("admits a compatible client and exposes the initial projection", async () => {
    const room = await connectTestClient({ protocolVersion: "current" });
    expect(room.state.phase).toBe("lobby");
  });

  it("rejects an invalid command without mutating state", async () => {
    const room = await connectTestClient({ protocolVersion: "current" });
    const before = snapshot(room.state);
    await room.send({ type: "input", commandId: "bad", sequence: -1, payload: { x: 999, y: 999 } });
    expect(snapshot(room.state)).toEqual(before);
  });

  it("does not apply a retried command twice", async () => {
    const room = await connectTestClient({ protocolVersion: "current" });
    const command = { type: "ready", commandId: "stable-command" };
    await room.send(command);
    const afterFirst = snapshot(room.state);
    await room.send(command);
    expect(snapshot(room.state)).toEqual(afterFirst);
  });

  it("keeps the seat across drop -> reconnect", async () => {
    const room = await connectTestClient({ protocolVersion: "current" });
    // Resume with the captured handle, never with the Colyseus sessionId:
    // sessionId is a per-player seat id, not a reconnection credential.
    // See references/reconnection.md §7.
    const handle = captureResumeHandle(room);
    const sessionId = room.sessionId;
    dropTransport(room); // no close code -> CloseCode.NO_STATUS_RECEIVED (1005)
    const resumed = await resumeTestClient(handle);
    expect(resumed.sessionId).toBe(sessionId);
    expect(resumed.roomId).toBe(handle.roomId);
    expect(resumed.state.phase).toBe(room.state.phase);
  });

  it("settles the seat when the reconnect grace period expires", async () => {
    // The client must stop auto-reconnecting here, otherwise the server sees a
    // reconnect instead of a grace-period expiry. The room's grace period is
    // shortened to seconds by the test fixture.
    const room = await connectTestClient({ protocolVersion: "current", reconnection: { enabled: false } });
    const sessionId = room.sessionId;
    dropTransport(room);
    const events = await waitForServerLeave(sessionId);
    // Grace-period expiry reuses the original drop code; onLeave is called a
    // second time on the drop path (references/reconnection.md §3.1-3.2).
    expect(events).toEqual([
      { type: "drop", sessionId, code: 1005 },
      { type: "leave", sessionId, code: 1005 },
    ]);
    expect(await seatOf(sessionId)).toBeUndefined();
  });

  it("does not allow reconnection after a consented leave", async () => {
    const room = await connectTestClient({ protocolVersion: "current" });
    const sessionId = room.sessionId;
    await room.leave(true); // CloseCode.CONSENTED (4000)
    // Consented leave goes straight to onLeave: no drop, no grace period.
    expect(await serverEventsFor(sessionId)).toEqual([{ type: "leave", sessionId, code: 4000 }]);
    expect(await seatOf(sessionId)).toBeUndefined();
  });

  it("fails closed on an expired resume handle", async () => {
    const handle = expiredResumeHandle();
    // An expired or released handle must clear the store and surface a stable
    // error instead of silently falling back to a fresh bootstrap.
    await expect(resumeFromTestClient(handle)).rejects.toMatchObject({ code: "INVALID_RESUME" });
    expect(readTestStore()).toBeUndefined();
  });

  it("cleans up timers and external effects on disposal", async () => {
    const room = await connectTestClient({ protocolVersion: "current" });
    await room.dispose();
    expect(room.openTimers()).toHaveLength(0);
  });
});

function snapshot(value: unknown) {
  return JSON.parse(JSON.stringify(value));
}

declare function connectTestClient(options: { protocolVersion: string; reconnection?: { enabled: boolean } }): Promise<any>;
declare function captureResumeHandle(room: any): { roomId: string; token: string };
declare function dropTransport(room: any): void;
declare function resumeTestClient(handle: { roomId: string; token: string }): Promise<any>;
declare function resumeFromTestClient(handle: unknown): Promise<any>;
declare function expiredResumeHandle(): unknown;
declare function readTestStore(): unknown;
declare function waitForServerLeave(sessionId: string): Promise<Array<{ type: string; sessionId: string; code: number }>>;
declare function serverEventsFor(sessionId: string): Promise<Array<{ type: string; sessionId: string; code: number }>>;
declare function seatOf(sessionId: string): Promise<unknown>;
